import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.161.0/build/three.module.js';

const canvas=document.querySelector('#scene');
const scene=new THREE.Scene();scene.background=new THREE.Color('#bfe0d0');scene.fog=new THREE.FogExp2('#c9dfc5',.0065);
const camera=new THREE.PerspectiveCamera(48,innerWidth/innerHeight,.1,300);
const renderer=new THREE.WebGLRenderer({canvas,antialias:true,alpha:false});renderer.setPixelRatio(Math.min(devicePixelRatio,1.8));renderer.setSize(innerWidth,innerHeight);renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.12;
scene.add(new THREE.HemisphereLight('#e9f4dc','#67845c',2.0));const sun=new THREE.DirectionalLight('#fff4d6',3.1);sun.position.set(-35,55,28);sun.castShadow=true;sun.shadow.mapSize.set(2048,2048);sun.shadow.camera.left=-80;sun.shadow.camera.right=80;sun.shadow.camera.top=80;sun.shadow.camera.bottom=-80;scene.add(sun);
const mat=(color,rough=.85)=>new THREE.MeshStandardMaterial({color,roughness:rough});
const M={grass:mat('#91b86b'),grass2:mat('#9fc779'),road:mat('#565e56'),roadLine:mat('#f3d982'),cream:mat('#f1e7c9'),white:mat('#f7f3e7'),green:mat('#557744'),darkgreen:mat('#34563b'),wood:mat('#a76d42'),roof:mat('#bd704e'),blue:mat('#83b8bd'),red:mat('#c95c43'),yellow:mat('#e7c968'),black:mat('#29352f'),glass:new THREE.MeshStandardMaterial({color:'#a9d8d6',roughness:.25,metalness:.1}),tire:mat('#27302d'),trunk:mat('#71543c'),leaf1:mat('#557f4d'),leaf2:mat('#709657'),leaf3:mat('#88a85b'),stone:mat('#c3c4a8'),pink:mat('#d99074')};
const world=new THREE.Group();scene.add(world);
const box=(parent,x,y,z,sx,sy,sz,material,cast=true)=>{const o=new THREE.Mesh(new THREE.BoxGeometry(sx,sy,sz),material);o.position.set(x,y,z);o.castShadow=cast;o.receiveShadow=true;parent.add(o);return o};
const cylinder=(parent,x,y,z,rt,rb,h,material,segments=8)=>{const o=new THREE.Mesh(new THREE.CylinderGeometry(rt,rb,h,segments),material);o.position.set(x,y,z);o.castShadow=true;o.receiveShadow=true;parent.add(o);return o};
const sphere=(parent,x,y,z,r,material,segments=12)=>{const o=new THREE.Mesh(new THREE.SphereGeometry(r,segments,segments),material);o.position.set(x,y,z);o.castShadow=true;o.receiveShadow=true;parent.add(o);return o};
const ground=new THREE.Mesh(new THREE.PlaneGeometry(190,190),M.grass);ground.rotation.x=-Math.PI/2;ground.position.y=-.12;ground.receiveShadow=true;world.add(ground);
// Soft rolling fields
for(let i=0;i<34;i++){const x=((i*43)%137)-68,z=((i*67)%139)-69;if(Math.abs(x)<8||Math.abs(z)<7)continue;const patch=new THREE.Mesh(new THREE.CircleGeometry(3+(i%4),12),i%3?M.grass:M.grass2);patch.rotation.x=-Math.PI/2;patch.position.set(x,-.1,z);patch.scale.set(1.3,.7,1);world.add(patch)}
// Roads run between the family places and village
function road(x,z,w,d){box(world,x,-.035,z,w,.09,d,M.road,false);if(w>d){for(let q=-w/2+2;q<w/2-1;q+=5)box(world,x+q,.015,z,w>d?.8:.1,.012,.09,M.roadLine,false)}else{for(let q=-d/2+2;q<d/2-1;q+=5)box(world,x,.015,z+q,.09,.012,.8,M.roadLine,false)}}
road(0,0,14,14);road(-9,0,68,5.2);road(0,13,5.2,34);road(9,28,5.2,38);road(-27,13,5.2,26);road(-27,-13,5.2,26);road(9,-12,5.2,27);road(29,0,5.2,34);road(27,28,42,5.2);
// scenery
function tree(x,z,s=1,forest=false){const g=new THREE.Group();g.position.set(x,0,z);world.add(g);cylinder(g,0,.7*s,0,.17*s,.23*s,1.4*s,M.trunk,7);if(forest){for(let i=0;i<3;i++){const cone=new THREE.Mesh(new THREE.ConeGeometry((1.05-i*.18)*s,.98*s,7),[M.leaf1,M.leaf2,M.leaf3][(i+Math.round(x))%3<0?0:(i+Math.round(x))%3]);cone.position.set(0,(1.6+i*.57)*s,0);cone.castShadow=true;g.add(cone)}}else{sphere(g,0,1.8*s,0,.95*s,[M.leaf2,M.leaf3][Math.abs(Math.round(x))%2],9)}return g}
for(let i=0;i<90;i++){let x=((i*37)%175)-87,z=((i*59)%175)-87;if(Math.abs(x)<13&&Math.abs(z)<13)continue;const nearForest=x>20&&x<70&&z>-22&&z<23;if(nearForest){x=25+(i*29%43);z=-22+(i*31%45)}else if(i%4===0&&Math.abs(x)<45&&Math.abs(z)<40)continue;tree(x,z,.72+(i%5)*.11,nearForest)}
// Farms and charming town architecture
function house(x,z,color,label,scale=1){const g=new THREE.Group();g.position.set(x,0,z);world.add(g);box(g,0,1.25,0,5.2*scale,2.5*scale,4.2*scale,M.white);box(g,0,2.72*scale,0,5.8*scale,.35*scale,4.7*scale,mat(color));const roof1=new THREE.Mesh(new THREE.ConeGeometry(4*scale,2*scale,4),mat(color));roof1.rotation.y=Math.PI/4;roof1.scale.set(1.05,.72,.84);roof1.position.set(0,3.55*scale,0);roof1.castShadow=true;g.add(roof1);box(g,0,.8*scale,2.12*scale,.9*scale,1.6*scale,.12*scale,M.wood);for(const q of [-1.6,1.6]){box(g,q,1.6*scale,2.15*scale,.75*scale,.65*scale,.1*scale,M.glass)}if(label)sign(g,0,4.2*scale,2.4*scale,label);return g}
function sign(parent,x,y,z,text){const canvas2=document.createElement('canvas');canvas2.width=512;canvas2.height=128;const c=canvas2.getContext('2d');c.fillStyle='#294735';c.beginPath();c.roundRect(2,2,508,124,18);c.fill();c.fillStyle='#eff2d8';c.font='bold 47px sans-serif';c.textAlign='center';c.textBaseline='middle';c.fillText(text.toUpperCase(),256,65);const tex=new THREE.CanvasTexture(canvas2);const m=new THREE.Mesh(new THREE.PlaneGeometry(4.4,.95),new THREE.MeshBasicMaterial({map:tex,transparent:true,side:THREE.DoubleSide}));m.position.set(x,y,z);parent.add(m)}
house(-3,4,'#b66c4e','HAY DAY FARM',1.0);box(world,4,.35,-2,4.6,.7,3.3,M.wood);box(world,4,.75,-2,4.8,.2,3.5,M.roof);for(let i=0;i<3;i++)box(world,2.8+i*1.1,.77,-2.04,.7,.7,.04,M.cream);
house(-30,20,'#b76b50','PARENTS',.9);house(-30,-20,'#6a9c7e','GRANDPARENTS',.9);
house(1,41,'#d19c57','MARKET',.9);house(18,41,'#799a70','PARTS',.85);house(35,41,'#a980b2','DECOR',.85);
// store awnings, pumps, produce
for(let x of [-.6,.8]){box(world,x,2.15,43.25,1,.65,.1,M.red)}
function pump(x,z){box(world,x,.72,z,.8,1.35,.72,M.white);box(world,x,.25,z,.94,.18,.84,M.red);box(world,x,1.15,z,.55,.42,.09,M.black);const h=new THREE.Mesh(new THREE.BoxGeometry(.13,.5,.13),M.black);h.position.set(x+.53,.9,z);world.add(h);box(world,x,1.49,z,.55,.16,.08,M.red)}
pump(11,28);pump(13,28);box(world,12,2.75,28,3,.18,2,M.red);sign(world,12,3,28,'GAS & GO');
// police station and car
house(38,28,'#6b8d9d','RANGER POST',.75);const copLamp=box(world,38,3.7,30,.18,.07,.07,M.red);
// little fence around farm
for(let i=0;i<9;i++){box(world,-9+i*1.2,.36,-5,.08,.72,.08,M.white);box(world,-9+i*1.2,.48,-5,.08,.09,.08,M.white)}box(world,-4,.32,-5,10,.12,.08,M.white);
// Cars are low-poly, stylized custom models
const vehicles={};
function makeCar(id,name,color,x,z,opts={}){const g=new THREE.Group();g.position.set(x,0,z);world.add(g);g.rotation.y=opts.rot||0;const paint=mat(color,.45);box(g,0,.64,0,opts.length||3.8,.65,1.8,paint);box(g,-.05,1.13,-.03,2.1,.78,1.55,paint);box(g,-.05,1.17,.77,1.9,.55,.04,M.glass);box(g,-.05,1.17,-.81,1.9,.55,.04,M.glass);box(g,1.02,1.12,0,.04,.57,.07,M.black);box(g,-1.12,.62,.92,.55,.25,.07,M.white);box(g,-1.12,.62,-.92,.55,.25,.07,M.white);box(g,1.88,.55,.55,.13,.23,.18,M.yellow);box(g,1.88,.55,-.55,.13,.23,.18,M.yellow);box(g,-1.89,.57,.56,.14,.23,.18,M.red);box(g,-1.89,.57,-.56,.14,.23,.18,M.red);const wheels=[];for(const wx of [-1.18,1.18])for(const wz of [-.94,.94]){const w=cylinder(g,wx,.43,wz,.39,.39,.22,M.tire,12);w.rotation.x=Math.PI/2;wheels.push(w);cylinder(g,wx,.43,wz+Math.sign(wz)*.12,.2,.2,.035,mat('#aeb5a5'),12)}
if(opts.truck){box(g,-.1,1.44,-.05,1.55,.12,1.68,M.glass);box(g,-1.35,1.12,0,1.3,.9,1.82,paint);box(g,-1.4,1.58,0,1.3,.12,1.9,mat('#e3d8b7'))}
if(opts.scooter){g.clear();box(g,0,.42,0,1.05,.18,.28,paint);cylinder(g,-.47,.37,0,.3,.3,.14,M.tire,12).rotation.x=Math.PI/2;cylinder(g,.47,.37,0,.3,.3,.14,M.tire,12).rotation.x=Math.PI/2;box(g,-.05,.87,0,.22,.85,.18,paint);box(g,.2,1.18,0,.75,.1,.1,M.black);box(g,-.3,1.12,0,.2,.12,.22,M.black)}
if(opts.broken){box(g,.1,1.53,0,.68,.08,1.15,M.black);box(g,.15,1.3,.05,.22,.06,.22,M.red)}
if(opts.police){box(g,0,1.05,0,2,.15,1.9,M.white);box(g,.2,1.55,0,.58,.14,.28,M.blue)}
vehicles[id]={id,name,group:g,wheels,speed:0,broken:!!opts.broken,usable:!opts.broken,opts};return vehicles[id]}
makeCar('truck','FARM TRUCK','#bd6745',7,-4,{truck:true,length:4.3,rot:Math.PI/2});makeCar('forestGolf','FOREST GOLF','#cfbd65',47,0,{broken:true,rot:Math.PI/2});makeCar('parentGolf','PARENTS\' GOLF','#5e9d83',-24,26,{rot:Math.PI/2});makeCar('logan','DACIA LOGAN','#7b8fa0',-24,-26,{rot:Math.PI/2});makeCar('scooter','SCOOTER','#e28550',-20,-26,{scooter:true});makeCar('bmw','YOUR BMW','#537c9e',2,-8,{rot:0});makeCar('police','RANGER PATROL','#f4f2dc',38,35,{police:true,rot:Math.PI});
// forest clearing and repair props
for(let i=0;i<9;i++){const x=34+(i*19%32),z=-16+(i*13%33);tree(x,z,.95+(i%3)*.2,true)}
// dog! low poly friendly pup
function makeDog(){const g=new THREE.Group();g.position.set(55,0,7);world.add(g);const fur=mat('#dba86e');sphere(g,0,.42,0,.46,fur);sphere(g,.32,.68,.02,.28,fur);sphere(g,.53,.78,.02,.07,M.black);sphere(g,.57,.67,.17,.045,M.black);sphere(g,.57,.67,-.13,.045,M.black);const ear=sphere(g,.22,.9,.2,.14,mat('#8c5a40'));ear.scale.set(.55,1.3,.65);const ear2=ear.clone();ear2.position.z=-.2;g.add(ear2);for(let x of [-.2,.2])for(let z of [-.22,.22])cylinder(g,x,.17,z,.07,.09,.32,fur,7);const tail=cylinder(g,-.48,.61,0,.07,.04,.48,fur,7);tail.rotation.z=-.8;return g}const dog=makeDog();
// location markers and interaction areas
const targets=[
{id:'farm',label:'Hay Day Farm',x:0,z:0,r:10}, {id:'forest',label:'Pinecone Forest',x:44,z:0,r:14},{id:'parents',label:'Parents’ Place',x:-28,z:22,r:11},{id:'grandparents',label:'Grandparents’ Cottage',x:-27,z:-22,r:11},{id:'village',label:'Little Village',x:14,z:39,r:12},{id:'gas',label:'Gas & Go',x:12,z:28,r:6}];
const objective={bmwParts:false,bmwBuilt:false,repairKit:false,golfFixed:false,dogFound:false,parentsVisited:false,grandVisited:false,marketVisited:false,decorVisited:false,policeVisited:false};
const discovered=new Set();let player={x:0,z:2,yaw:0,vehicle:null};const keys={};let joy={x:0,y:0};let activeTarget=null,modalMode='';
const missionData=[['🔩','Build your BMW','Find the parts & build it at the farm'],['🛠️','Fix the forest Golf','A repair kit makes it road-ready'],['🐕','Find your forest friend','There’s a pup among the pines'],['🚙','Visit the family','Check in at both family homes'],['⛽','Take the truck for a fill-up','A full tank for the next adventure'],['✨','Make the village yours','Browse the market & decor shop']];
function completed(index){return [objective.bmwBuilt,objective.golfFixed,objective.dogFound,objective.parentsVisited&&objective.grandVisited,discovered.has('gas'),objective.marketVisited&&objective.decorVisited][index]}
function renderMissions(){const list=document.querySelector('#missionList');list.innerHTML=missionData.map((m,i)=>`<div class="mission ${completed(i)?'done':''}" data-i="${i}"><span class="mission-icon">${m[0]}</span><div class="mission-copy"><div class="mission-title">${m[1]}</div><div class="mission-sub">${m[2]}</div></div><span class="check">${completed(i)?'✓':''}</span></div>`).join('');document.querySelector('#progressText').textContent=`${discovered.size} / ${targets.length} discoveries`}
renderMissions();
function toast(msg){const el=document.querySelector('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),2300)}
function mark(id){if(!discovered.has(id)){discovered.add(id);renderMissions();const t=targets.find(a=>a.id===id);toast(`New place discovered · ${t.label}`)}}
function modal(title,body,icon='✦'){document.querySelector('#modalContent').innerHTML=`<div class="modal-hero">${icon}</div><span class="eyebrow">LITTLE ROADS · FARM & FOREST</span><h2>${title}</h2>${body}`;document.querySelector('#modalBackdrop').classList.add('open')}
function closeModal(){document.querySelector('#modalBackdrop').classList.remove('open');modalMode=''}document.querySelector('#modalClose').onclick=closeModal;document.querySelector('#modalBackdrop').addEventListener('pointerdown',e=>{if(e.target.id==='modalBackdrop')closeModal()});
function interact(target){if(!target)return;if(target.type==='vehicle'){const v=target.vehicle;if(v.broken){if(objective.repairKit){modal('A little tune-up',`<p>You pop the hood, fit the new parts, and give the Golf a loving tune-up. It purrs back to life!</p><button class="modal-action" data-action="fix-golf">Repair the Golf <span>Use repair kit</span></button>`,'🛠️')}else modal('The Golf needs some love',`<p>This little Golf has seen better days. Find a repair kit at the Parts Store, then come back to get it running.</p><div class="modal-foot">Tip: the Parts Store is just east of the village market.</div>`,'🚙');return}
if(player.vehicle===v){exitVehicle();return}if(player.vehicle){toast('Hop out of your current ride first');return}if(v.id==='bmw'&&!objective.bmwBuilt){modal('A project in progress',`<p>This is your BMW build! Gather the pieces at the Parts Store, then use the farm workbench to put it together.</p>`,'🚘');return}enterVehicle(v);return}
if(target.type==='dog'){if(!objective.dogFound){objective.dogFound=true;dog.rotation.y=Math.PI;renderMissions();toast('You found Biscuit! What a good dog 🐾');modal('Meet Biscuit!',`<p>A friendly pup was hiding in the forest clearing. Biscuit is thrilled to have a new road-trip buddy!</p><div class="modal-foot">Discovery added to your adventure journal.</div>`,'🐕')}else modal('Biscuit',`<p>Biscuit wags their tail and trots beside you. Best co-pilot ever.</p>`,'🐾');return}
if(target.type==='station'){if(target.id==='parts'){openShop('parts');return}if(target.id==='decor'){openShop('decor');return}if(target.id==='market'){openShop('market');return}if(target.id==='gas'){mark('gas');modal('Gas & Go',`<p>Ready to top up? This is the perfect pit stop between family visits.</p><button class="modal-action" data-action="fuel">Fill the tank <span>Free today</span></button>`,'⛽');return}if(target.id==='farmbench'){openBench();return}if(target.id==='police'){mark('village');objective.policeVisited=true;modal('Ranger Post',`<p>The friendly countryside patrol keeps these roads safe. Wave hello and carry on exploring!</p>`,'🚨');return}}
if(target.type==='place'){mark(target.id);if(target.id==='parents'){objective.parentsVisited=true;modal('Parents’ Place',`<p>Your parents are out in the garden. Their green Golf is parked and ready for a spin!</p><div class="modal-foot">Family visit checked off.</div>`,'🏡')}else if(target.id==='grandparents'){objective.grandVisited=true;modal('Grandparents’ Cottage',`<p>Grandma and Grandpa have tea on the porch. Their Dacia Logan and little scooter are parked outside.</p><div class="modal-foot">Family visit checked off.</div>`,'🏡')}else if(target.id==='forest'){mark('forest');modal('Pinecone Forest',`<p>Follow the little trails through the pines. There’s a loyal friend waiting in a clearing.</p>`,'🌲')}else if(target.id==='farm'){modal('Hay Day Farm',`<p>Home sweet home! Your truck is ready, and your BMW build is waiting by the barn.</p>`,'🌾')}else {mark('village');modal('Little Village',`<p>A few friendly shops, a gas stop, and the Ranger Post. Everything you need for a perfect road trip.</p>`,'🏘️')}}}
function openShop(kind){const config={parts:['Parts Store','🔩','The good stuff for every roadside project.'],market:['Farmers’ Market','🍎','Fresh-picked snacks for your family road trip.'],decor:['Little Nest Decor','✨','Make your farm feel a little more like you.']}[kind];let extra=kind==='parts'?`<button class="modal-action" data-action="buy-parts">BMW build kit <span>${objective.bmwParts?'Owned':'3 pieces · FREE'}</span></button><button class="modal-action" data-action="buy-repair">Golf repair kit <span>${objective.repairKit?'Owned':'FREE'}</span></button>`:kind==='market'?`<button class="modal-action" data-action="market">Picnic basket <span>Take one · FREE</span></button><button class="modal-action" data-action="market">Apple juice <span>Take one · FREE</span></button>`:`<button class="modal-action" data-action="decor">Flower boxes <span>Place at farm · FREE</span></button><button class="modal-action" data-action="decor">Windmill ornament <span>Take home · FREE</span></button>`;modal(config[0],`<p>${config[2]}</p>${extra}<div class="modal-foot">A friendly neighborhood shop. No coins needed!</div>`,config[1]);modalMode=kind}
function openBench(){if(!objective.bmwParts){modal('Your BMW workbench',`<p>Three special pieces are missing. Pop into the Parts Store in the village, then bring them back here.</p>`,'🔧');return}if(!objective.bmwBuilt){modal('Build your BMW',`<p>All the pieces are here! Ready to build your very own road-ready BMW?</p><button class="modal-action" data-action="build-bmw">Put it together <span>Let’s go!</span></button>`,'🚘')}else modal('Looking sharp!',`<p>Your BMW is ready to roll. The open road is calling!</p>`,'✨')}
document.querySelector('#modalContent').addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;if(a==='buy-parts'){objective.bmwParts=true;toast('BMW pieces collected · all 3 parts!');renderMissions();openShop('parts')}if(a==='buy-repair'){objective.repairKit=true;toast('Repair kit added to your bag');openShop('parts')}if(a==='build-bmw'){objective.bmwBuilt=true;vehicles.bmw.usable=true;vehicles.bmw.group.scale.setScalar(1.05);renderMissions();closeModal();toast('Your BMW is ready to hit the road! 🚘')}if(a==='fix-golf'){objective.golfFixed=true;vehicles.forestGolf.broken=false;vehicles.forestGolf.usable=true;const g=vehicles.forestGolf.group;g.children.filter(o=>o.material===M.black).forEach(o=>o.visible=true);renderMissions();closeModal();toast('The forest Golf is fixed! Nice work.')}if(a==='fuel'){closeModal();toast('Tank topped up · you’re good to go!')}if(a==='market'){objective.marketVisited=true;closeModal();toast('Picnic treats packed for the road!')}if(a==='decor'){objective.decorVisited=true;closeModal();toast('A little farmhouse charm, coming right up!')} });
function enterVehicle(v){player.vehicle=v;v.speed=0;document.querySelector('#vehicleHud').classList.add('active');document.querySelector('#vehicleName').textContent=v.name;document.querySelector('#driveBtn').querySelector('small').textContent='EXIT';toast(`Hop in the ${v.name.toLowerCase()}!`)}
function exitVehicle(){if(!player.vehicle)return;player.x=player.vehicle.group.position.x+1.9;player.z=player.vehicle.group.position.z;player.yaw=player.vehicle.group.rotation.y;player.vehicle.speed=0;player.vehicle=null;document.querySelector('#vehicleHud').classList.remove('active');document.querySelector('#driveBtn').querySelector('small').textContent='DRIVE';toast('Back on foot · stretch your legs!')}
// Interactable signs, buildings, cars, dog, places
const staticTargets=[{type:'station',id:'farmbench',label:'Farm workbench',x:4,z:-2,r:3},{type:'station',id:'market',label:'Farmers’ Market',x:1,z:41,r:4},{type:'station',id:'parts',label:'Parts Store',x:18,z:41,r:4},{type:'station',id:'decor',label:'Decor Store',x:35,z:41,r:4},{type:'station',id:'gas',label:'Gas & Go',x:12,z:28,r:4},{type:'station',id:'police',label:'Ranger Post',x:38,z:28,r:4},{type:'dog',id:'dog',label:'Biscuit the dog',x:55,z:7,r:2.8}];
function getPos(){return player.vehicle?player.vehicle.group.position:player}
function updateTarget(){const p=getPos();let nearest=null,dist=Infinity;for(const v of Object.values(vehicles)){if(v.id==='police')continue;const d=Math.hypot(p.x-v.group.position.x,p.z-v.group.position.z);if(d<dist&&d<4){nearest={type:'vehicle',vehicle:v,label:v.broken&&!objective.repairKit?'Broken Golf':`Get in ${v.name}`};dist=d}}
for(const t of staticTargets){const d=Math.hypot(p.x-t.x,p.z-t.z);if(d<t.r&&d<dist){nearest=t;dist=d}}
if(!nearest&&!player.vehicle)for(const t of targets){const d=Math.hypot(p.x-t.x,p.z-t.z);if(d<7&&d<dist){nearest={type:'place',id:t.id,label:`Explore ${t.label}`};dist=d}}
activeTarget=nearest;const ui=document.querySelector('#interaction');if(nearest&&!player.vehicle){ui.classList.add('visible');document.querySelector('#interactionText').textContent=nearest.label}else ui.classList.remove('visible');
for(const t of targets){const d=Math.hypot(p.x-t.x,p.z-t.z);if(d<t.r)mark(t.id)}
const loc=targets.reduce((a,b)=>Math.hypot(p.x-a.x,p.z-a.z)<Math.hypot(p.x-b.x,p.z-b.z)?a:b);document.querySelector('#locationName').textContent=loc.label.toUpperCase();}
